from pathlib import Path
import hashlib,json,datetime
root=Path.cwd(); out=root/'docs/codex-queue/244'

if (out/'prompts.json').exists(): raise SystemExit('Prompt đã có; tiếp tục từ calls.json, không ghi đè.')
games=['dragon-hold','typing-defense','typing-survival']
before={str(p.relative_to(root)):hashlib.md5(p.read_bytes()).hexdigest() for g in games for p in sorted((root/f'games/{g}/art-src/ui/quick-settings').rglob('*')) if p.is_file()}
if not (out/'md5-before.json').exists():
 (out/'md5-before.json').write_text(json.dumps(before,indent=2)+'\n')
 (out/'md5-before.txt').write_text(''.join(f'{v}  {k}\n' for k,v in before.items()))
small='SMALL-SIZE: designed to be read at 20-32 pixels in a game menu. One chunky, closed silhouette that fills the frame. A thick dark outline about 5-6 percent of the icon width all round. Large simple shapes only: no thin rods, spokes, rings, filigree, chains or hair-thin lines. At most one bright accent colour. Surface engraving only as faint texture that may vanish at small size. No text, no numbers, no frame or background plate.'
items=[('dragon-hold','vol-keyboard','one front-facing keycap (a square with a bevelled top and a dark letter-free face) with two curved sound arcs to its right, ember gold with a dark outline'),('dragon-hold','vol-voice','a speech bubble with a clear pointed tail and two sound arcs, thick gold outline, dark filled centre'),('dragon-hold','vol-interface','a bold upright mouse-pointer arrow pressing a small round button, with a tiny click star, one gold silhouette'),('dragon-hold','vol-keyboard-volume','a keycap on the left with three rising volume bars on the right, ember gold'),('typing-defense','vol-keyboard','one front-facing jade keycap in a gold rim, letter-free face, with two sound arcs to its right'),('typing-defense','vol-interface','an upright pointer arrow tapping a round jade button, with a small click spark, gold silhouette with a dark outline'),('typing-defense','vol-keyboard-volume','a jade keycap with three rising gold volume bars'),('typing-defense','hud-settings','a gear with solid teeth joined to a thick gold body and a dark hub, set on a round jade plate')]
jobs=[]
for g,n,subject in items:
 base=root/f'games/{g}/art-src/ui/quick-settings'; old=(base/'selected/vol-master.prompt.txt').read_text(); style=old.split('\n\nICON')[0]; kind=old.split('\n\nICON\n')[1].split('\n\n')[0]
 prompt=style+'\n\nKIND ICON:\n'+kind+'\n\n'+small+'\n\n'+subject+'.\n\nProduction layout: one centered complete icon, square 1024 x 1024 canvas. The entire silhouette occupies 70 percent of the canvas long edge. The SMALL-SIZE dark outline and the specific front-facing subject take priority over the older three-quarter ICON defaults. Render broad polished gold bevels and simple dark recesses; keep the visual masses bold enough for 24 pixels. '+('The round jade plate is an integral gear backing, as specifically requested for this object. ' if n=='hud-settings' else '')+'The right-side arcs or rising bars, when requested, are thick and separated by large clear gaps.\nReference images: Image 1 and Image 2 are this game’s approved vol-master and hud-sound icons; match their material finish, with much simpler surface detail. Reference content is not part of the requested object.\nBackground: perfectly flat solid magenta #FF00FF, including all holes. No magenta on the object, no reflected magenta, no background gradient or shadow.\n'
 stem=n+('.try1' if n=='vol-keyboard-volume' else '.r2-try1'); rel=str((base/f'{stem}.png').relative_to(root))
 jobs.append(dict(game=g,name=n,type='icon',output=rel,prompt=prompt,references=[str((base/f'selected/{r}.png').relative_to(root)) for r in ['vol-master','hud-sound']]))
for g,n,subject in [('dragon-hold','slider-fill','the same groove, its channel filled with a molten ember-gold core that glows warm orange, the gold rims and end caps unchanged'),('typing-defense','slider-fill','the same groove, its channel filled with bright polished jade lit from within, gold-leaf rims unchanged'),('typing-defense','slider-empty','the same groove, its channel dark unpolished stone with a faint bronze tint, clearly darker than the jade fill, rims and caps unchanged'),('typing-survival','slider-fill','the same groove, the smoked glass filled with bright electric-cyan energy, white-gold rims and caps unchanged')]:
 base=root/f'games/{g}/art-src/ui/quick-settings/sliders'; old=(base/'slider-track.prompt.txt').read_text(); style=old.split('\n\n')[0]; part=old.split('\n\n')[1]
 prompt=style+'\n\n'+part+'\n\nUse case: precise-object-edit. Image 1 is the edit target: this game’s current slider-track.png, the exact silhouette to preserve. Change ONLY the material inside the recessed working channel. Primary request: '+subject+'.\nKeep the same gold rims, cap artwork, physical outline, alpha silhouette, geometry, straight-on view, framing and position. All long-edge thicknesses and both end locations remain identical. The working channel has an even continuous material from end to end, with restrained texture and uniform average brightness. '+('Make the empty channel clearly dark, unlit and matte. ' if n=='slider-empty' else 'The luminous working channel is substantially brighter than the empty track by at least 0.15 in sRGB luma. Its warm or cyan or jade emission stays entirely inside the opaque channel. ')+'The result is a single complete rail with the same 16:1 shape as the target. Preserve the target’s 1024 x 64 framing if possible. If a taller canvas is required, keep the complete ultra-wide rail centered with empty transparent space around it; keep its width-to-height ratio and both end caps exactly. No knob, fill boundary, tick marks, text, symbols, extra objects or external glow.\nBackground: actual transparent background, RGBA. Solid opaque material inside the groove, antialiasing only at the physical boundary.\n'
 jobs.append(dict(game=g,name=n,type='slider',output=str((base/f'{n}.try1.png').relative_to(root)),prompt=prompt,references=[str((base/'slider-track.png').relative_to(root))]))
(out/'prompts.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
print(json.dumps([{'game':j['game'],'name':j['name'],'output':j['output']} for j in jobs],indent=2))
